<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'admin' })
const route = useRoute(); const API_URL = 'http://localhost:8000'; const book = ref<any | null>(null); const loading = ref(true)
onMounted(async () => { try { book.value = await $fetch<any>(`${API_URL}/books/${route.params.id}`) } finally { loading.value = false } })
</script>
<template><section><div class="mb-8"><p class="text-[10px] font-bold uppercase tracking-[0.24em] text-primary">Catalog</p><h1 class="mt-2 font-serif text-3xl font-bold tracking-tight text-ink sm:text-4xl">Book details</h1></div><div v-if="loading" class="py-20 text-center text-sm text-gray-500">Loading...</div><div v-else-if="book" class="grid max-w-4xl gap-8 rounded-2xl border border-[#d9e7e2] bg-white p-6 shadow-sm sm:grid-cols-[180px_1fr] sm:p-8"><img :src="book.image" :alt="book.title" class="h-64 w-full rounded-xl object-cover sm:h-56" /><div><div class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-xs font-bold uppercase tracking-[0.18em] text-primary">{{ book.category }} · {{ book.format }}</p><h2 class="mt-3 font-serif text-3xl font-bold text-ink">{{ book.title }}</h2><p class="mt-2 text-gray-500">by {{ book.author }}</p></div><NuxtLink :to="`/admin/books/edit/${book.id}`" class="inline-flex items-center gap-1.5 rounded-xl bg-primary px-4 py-2 text-sm font-semibold text-white">
                <UiIcon name="edit" class="h-4 w-4" /> Edit</NuxtLink></div><div class="mt-8 grid grid-cols-3 gap-3"><div class="rounded-xl bg-[#f3f9f7] p-4"><p class="text-xs text-gray-500">Price</p><p class="mt-1 font-bold text-ink">${{ Number(book.price).toFixed(2) }}</p></div><div class="rounded-xl bg-[#f3f9f7] p-4"><p class="text-xs text-gray-500">Rating</p><p class="mt-1 font-bold text-ink">{{ book.rating }}/5</p></div><div class="rounded-xl bg-[#f3f9f7] p-4"><p class="text-xs text-gray-500">Reviews</p><p class="mt-1 font-bold text-ink">{{ book.reviews || 0 }}</p></div></div></div></div><p v-else class="rounded-xl bg-red-50 p-4 text-sm text-red-700">Book not found.</p></section></template>
